<?php
require_once '../includes/auth.php'; require_role('admin'); require_once '../config/db.php'; require_once '../includes/academic.php';
$page_title='Timetable & Teaching Assignments'; $msg=''; $err='';
$days=[1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday'];
$hours=[1=>['09:00','10:00'],2=>['10:15','11:15'],3=>['11:15','12:15'],4=>['13:45','14:45'],5=>['15:00','16:00']];
$courses=['BCA','BBA','BCom','BSC Computer Science'];
$semester=(int)($_GET['semester']??$_POST['semester']??1); if($semester<1||$semester>8)$semester=1;
$selected=(int)($_GET['batch_id']??$_POST['batch_id']??0);

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(isset($_POST['create_batch'])){
        $name=trim($_POST['batch_name']??'');$course=trim($_POST['course']??'');$admissionYear=(int)($_POST['admission_year']??date('Y'));
        $duration=course_duration_years($course); if(!$name)$name=$course.' '.$admissionYear.' Cohort';
        if(!in_array($course,$courses,true)||$admissionYear<2000||$admissionYear>date('Y')+1)$err='Choose a valid course and admission year.';
        else{$st=$conn->prepare("INSERT INTO tbl_batches(batch_name,course,semester,admission_year,duration_years) VALUES(?,?,1,?,?)");$st->bind_param('ssii',$name,$course,$admissionYear,$duration);if($st->execute()){$selected=$st->insert_id;$msg='Academic batch created. Students in this cohort will progress automatically by semester.';}else$err='This cohort already exists or could not be created.';}
    }
    if(isset($_POST['create_teaching_assignment'])){
        $teacher=trim($_POST['teacher_username']??'');$batch=(int)($_POST['batch_id']??0);$sem=(int)($_POST['semester']??1);$subject=trim($_POST['subject']??'');
        $st=$conn->prepare("SELECT id,batch_name,course,duration_years FROM tbl_batches WHERE id=? AND active=1");$st->bind_param('i',$batch);$st->execute();$b=$st->get_result()->fetch_assoc();
        if(!$b||!$teacher||!$subject||$sem<1||$sem>(int)$b['duration_years']*2)$err='Select a valid teacher, batch, semester and subject.';
        else{$st=$conn->prepare("SELECT username FROM tbl_trs WHERE username=? AND approved=1");$st->bind_param('s',$teacher);$st->execute();if(!$st->get_result()->fetch_assoc())$err='Select an active teacher.';else{$st=$conn->prepare("INSERT INTO tbl_teacher_teaching(teacher_username,batch_id,semester,subject) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE active=1");$st->bind_param('siis',$teacher,$batch,$sem,$subject);if($st->execute())$msg='Teaching assignment saved for '.$b['batch_name'].' · Semester '.$sem.'.';else$err='Could not save the teaching assignment.';}}
    }
    if(isset($_POST['delete_teaching_assignment'])){$id=(int)$_POST['teaching_assignment_id'];$st=$conn->prepare("SELECT COUNT(*) c FROM tbl_timetable WHERE teaching_assignment_id=?");$st->bind_param('i',$id);$st->execute();$used=(int)$st->get_result()->fetch_assoc()['c'];if($used)$err='This teaching assignment is used by the timetable. Remove its timetable slots first.';else{$st=$conn->prepare("DELETE FROM tbl_teacher_teaching WHERE id=?");$st->bind_param('i',$id);$st->execute();$msg='Teaching assignment removed.';}}
    if(isset($_POST['save_slot'])){
        $ta=(int)$_POST['teaching_assignment_id'];$day=(int)$_POST['day_of_week'];$hour=(int)$_POST['hour_no'];
        $st=$conn->prepare("SELECT ta.id,ta.batch_id,ta.semester,ta.subject,ta.teacher_username FROM tbl_teacher_teaching ta JOIN tbl_batches b ON b.id=ta.batch_id WHERE ta.id=? AND ta.active=1 AND b.active=1");$st->bind_param('i',$ta);$st->execute();$a=$st->get_result()->fetch_assoc();
        if(!$a||$day<1||$day>6||$hour<1||$hour>5)$err='Choose a valid teaching assignment, day and hour.';else{$start=$hours[$hour][0];$end=$hours[$hour][1];$st=$conn->prepare("INSERT INTO tbl_timetable(batch_id,semester,teaching_assignment_id,day_of_week,hour_no,subject,teacher_username,start_time,end_time) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE teaching_assignment_id=VALUES(teaching_assignment_id),subject=VALUES(subject),teacher_username=VALUES(teacher_username),start_time=VALUES(start_time),end_time=VALUES(end_time)");$st->bind_param('iiiiissss',$a['batch_id'],$a['semester'],$ta,$day,$hour,$a['subject'],$a['teacher_username'],$start,$end);if($st->execute()){$selected=(int)$a['batch_id'];$semester=(int)$a['semester'];$msg='Timetable slot saved for Semester '.$semester.'.';}else$err='Could not save timetable slot.';}
    }
    if(isset($_POST['delete_slot'])){$id=(int)$_POST['slot_id'];$st=$conn->prepare("DELETE FROM tbl_timetable WHERE id=?");$st->bind_param('i',$id);$st->execute();$msg='Timetable slot removed.';}
}

$batchList=[];$r=$conn->query("SELECT b.*,COUNT(s.username) student_count FROM tbl_batches b LEFT JOIN tbl_student s ON s.batch_id=b.id AND s.approved=1 WHERE b.active=1 GROUP BY b.id ORDER BY b.course,b.admission_year,b.batch_name");while($x=$r->fetch_assoc())$batchList[]=$x;
if(!$selected && $batchList)$selected=(int)$batchList[0]['id'];
$selectedBatch=null;foreach($batchList as $b){if((int)$b['id']===$selected){$selectedBatch=$b;break;}}
$maxSem=$selectedBatch?(int)$selectedBatch['duration_years']*2:8;if($semester>$maxSem)$semester=1;
$teacherList=[];$r=$conn->query("SELECT username,name FROM tbl_trs WHERE approved=1 ORDER BY name");while($x=$r->fetch_assoc())$teacherList[]=$x;
$teachingList=[];$st=$conn->prepare("SELECT ta.*,t.name teacher_name,b.batch_name,b.course FROM tbl_teacher_teaching ta JOIN tbl_trs t ON t.username=ta.teacher_username JOIN tbl_batches b ON b.id=ta.batch_id WHERE ta.active=1 AND ta.batch_id=? AND ta.semester=? ORDER BY t.name,ta.subject");$st->bind_param('ii',$selected,$semester);$st->execute();$r=$st->get_result();while($x=$r->fetch_assoc())$teachingList[]=$x;
$grid=[];$st=$conn->prepare("SELECT tt.*,t.name teacher_name FROM tbl_timetable tt JOIN tbl_trs t ON t.username=tt.teacher_username WHERE tt.batch_id=? AND tt.semester=? ORDER BY tt.day_of_week,tt.hour_no");$st->bind_param('ii',$selected,$semester);$st->execute();$r=$st->get_result();while($x=$r->fetch_assoc())$grid[$x['day_of_week']][$x['hour_no']]=$x;
require '../includes/header.php';
?>
<div class="glass-hero mb-4"><div><span class="eyebrow-dark">ADMINISTRATION</span><h2>Timetable & teaching assignments</h2><p>Create the permanent course cohort once. Then manage teacher subjects semester-by-semester and place them into the fixed five-hour timetable.</p></div><div class="hero-orb"><i class="fa-solid fa-calendar-week"></i></div></div>
<?php if($msg):?><div class="alert alert-success glass-alert"><?php echo e($msg);?></div><?php endif;?><?php if($err):?><div class="alert alert-danger glass-alert"><?php echo e($err);?></div><?php endif;?>
<div class="hour-strip glass-card mb-4"><div><strong>Fixed daily timing</strong><span class="small-muted">The times are automatic.</span></div><div class="hour-chip"><b>H1</b> 09:00–10:00</div><div class="break-chip">Break · 10:00–10:15</div><div class="hour-chip"><b>H2</b> 10:15–11:15</div><div class="hour-chip"><b>H3</b> 11:15–12:15</div><div class="break-chip">Lunch · 12:15–13:45</div><div class="hour-chip"><b>H4</b> 13:45–14:45</div><div class="break-chip">Break · 14:45–15:00</div><div class="hour-chip"><b>H5</b> 15:00–16:00</div></div>
<div class="glass-card mb-4"><div class="section-kicker">ACADEMIC COHORT</div><div class="d-flex flex-wrap justify-content-between align-items-center gap-3"><div><h5 class="mb-1">Course & batch are selected once</h5><p class="small-muted mb-0">Students remain in this cohort. Their semester changes automatically from the admission year.</p></div><div class="cohort-current"><?php echo e($selectedBatch?($selectedBatch['course'].' · '.$selectedBatch['batch_name'].' · Admission '.$selectedBatch['admission_year']):'No cohort'); ?></div></div><form method="POST" class="row g-3 mt-2"><input type="hidden" name="create_batch" value="1"><div class="col-md-4"><label class="form-label">Batch name</label><input class="form-control" name="batch_name" value="<?php echo e($selectedBatch['batch_name']??'BCA '.date('Y').' Cohort'); ?>" required></div><div class="col-md-3"><label class="form-label">Course</label><select class="form-select" name="course"><?php foreach($courses as $c):?><option value="<?php echo e($c);?>" <?php echo (($selectedBatch['course']??'BCA')===$c)?'selected':'';?>><?php echo e($c);?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Admission year</label><select class="form-select" name="admission_year"><?php for($y=date('Y')+1;$y>=date('Y')-5;$y--):?><option><?php echo $y;?></option><?php endfor;?></select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Create Cohort</button></div></form></div>
<div class="glass-card mb-4"><div class="d-flex flex-wrap justify-content-between align-items-center gap-3"><div><div class="section-kicker">SEMESTER WORKSPACE</div><h5 class="mb-1"><?php echo e($selectedBatch?($selectedBatch['course'].' · '.$selectedBatch['batch_name']):'Select a cohort'); ?></h5></div><select class="form-select" style="max-width:320px" onchange="location='timetable.php?batch_id='+this.value+'&semester=<?php echo $semester;?>'"><?php foreach($batchList as $b):?><option value="<?php echo $b['id'];?>" <?php echo $selected===(int)$b['id']?'selected':'';?>><?php echo e($b['course'].' · '.$b['batch_name'].' · Admission '.$b['admission_year']);?></option><?php endforeach;?></select></div>
<div class="semester-tabs mt-4"><?php for($s=1;$s<=$maxSem;$s++):?><a class="semester-tab <?php echo $semester===$s?'active':'';?>" href="?batch_id=<?php echo $selected;?>&semester=<?php echo $s;?>">Sem <?php echo $s;?><small>Year <?php echo (int)ceil($s/2);?></small></a><?php endfor;?></div></div>
<div class="row g-4"><div class="col-xl-4"><div class="glass-card mb-4"><div class="section-kicker">SEMESTER <?php echo $semester;?> SUBJECTS</div><h5>Assign teachers</h5><p class="small-muted">A teacher can appear in several semesters with a different subject in each one.</p><form method="POST"><input type="hidden" name="create_teaching_assignment" value="1"><input type="hidden" name="batch_id" value="<?php echo $selected;?>"><input type="hidden" name="semester" value="<?php echo $semester;?>"><label class="form-label">Teacher</label><select class="form-select mb-3" name="teacher_username" required><option value="">Select teacher</option><?php foreach($teacherList as $t):?><option value="<?php echo e($t['username']);?>"><?php echo e($t['name']);?></option><?php endforeach;?></select><label class="form-label">Subject for Semester <?php echo $semester;?></label><input class="form-control mb-3" name="subject" placeholder="Data Structures" required><button class="btn btn-primary w-100">Save Semester Subject</button></form><div class="mt-4"><?php if(!$teachingList):?><div class="empty">No teacher subjects assigned for this semester yet.</div><?php endif;?><?php foreach($teachingList as $ta):?><div class="glass-subcard p-3 mb-2"><strong><?php echo e($ta['teacher_name']);?></strong><div class="subject-line"><?php echo e($ta['subject']);?></div><span class="small-muted"><?php echo e($ta['batch_name']);?> · Sem <?php echo $semester;?></span><form method="POST" class="mt-2" onsubmit="return confirm('Remove this teaching assignment?');"><input type="hidden" name="delete_teaching_assignment" value="1"><input type="hidden" name="teaching_assignment_id" value="<?php echo (int)$ta['id'];?>"><button class="btn btn-sm btn-outline-danger">Remove</button></form></div><?php endforeach;?></div></div>
<div class="glass-card"><div class="section-kicker">SET A CLASS</div><h5>Place in timetable</h5><form method="POST"><input type="hidden" name="save_slot" value="1"><label class="form-label">Teacher · Subject</label><select class="form-select mb-3" name="teaching_assignment_id" required><option value="">Select</option><?php foreach($teachingList as $ta):?><option value="<?php echo (int)$ta['id'];?>"><?php echo e($ta['teacher_name'].' · '.$ta['subject']);?></option><?php endforeach;?></select><div class="row g-2"><div class="col-6"><label class="form-label">Day</label><select class="form-select" name="day_of_week"><?php foreach($days as $n=>$d):?><option value="<?php echo $n;?>"><?php echo $d;?></option><?php endforeach;?></select></div><div class="col-6"><label class="form-label">Hour</label><select class="form-select" name="hour_no"><?php foreach($hours as $n=>$time):?><option value="<?php echo $n;?>">Hour <?php echo $n;?> · <?php echo $time[0].'–'.$time[1];?></option><?php endforeach;?></select></div></div><button class="btn btn-primary w-100 mt-3">Save Timetable Hour</button></form></div></div>
<div class="col-xl-8"><div class="glass-card"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2"><div><div class="section-kicker">SEMESTER <?php echo $semester;?> · WEEKLY VIEW</div><h5 class="mb-1">5-hour timetable</h5><span class="small-muted">Only subjects assigned to this semester can be placed here.</span></div></div><div class="timetable-wrap mt-4"><table class="table timetable-table modern-timetable"><thead><tr><th>Day</th><?php foreach($hours as $h=>$time):?><th><span>Hour <?php echo $h;?></span><small><?php echo $time[0].'–'.$time[1];?></small></th><?php endforeach;?></tr></thead><tbody><?php foreach($days as $dn=>$day):?><tr><th><?php echo $day;?></th><?php for($h=1;$h<=5;$h++):$slot=$grid[$dn][$h]??null;?><td><?php if($slot):?><div class="tt-cell"><strong><?php echo e($slot['subject']);?></strong><span><?php echo e($slot['teacher_name']);?></span><small><?php echo e(substr($slot['start_time'],0,5));?>–<?php echo e(substr($slot['end_time'],0,5));?></small><form method="POST"><input type="hidden" name="delete_slot" value="1"><input type="hidden" name="slot_id" value="<?php echo (int)$slot['id'];?>"><button class="tt-delete" title="Remove this slot">×</button></form></div><?php else:?><span class="tt-empty">Not assigned</span><?php endif;?></td><?php endfor;?></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php require '../includes/footer.php'; ?>
